// Brand marks come from Simple Icons, which is CC0; the marks themselves stay with their owners.
// Each mark is drawn on a 24-unit grid: `fill` is one filled path, `stroke` is line art.

export type ArchMark = { fill: string } | { stroke: string[] };

export interface ArchRoleIcon {
  name: string;
  description: string;
  category: string;
  mark: ArchMark;
}

export interface ArchTypeIcon {
  name: string;
  category: string;
  alternatives: string[];
  mark: ArchMark;
}

